"""Grandfather-father-son snapshot retention. See task.md."""

from __future__ import annotations

import re
from datetime import datetime
from typing import Callable, NamedTuple


class RetentionError(ValueError):
    """Raised for an unusable policy or an unusable list of snapshots."""


class Kept(NamedTuple):
    snapshot: str
    reasons: tuple[str, ...]


_SHAPE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}")
_FORMAT = "%Y-%m-%dT%H:%M:%S"

_RULES = ("last", "hourly", "daily", "weekly", "monthly", "yearly")

_BUCKET: dict[str, Callable[[datetime], object]] = {
    "last": lambda t: t,
    "hourly": lambda t: (t.date(), t.hour),
    "daily": lambda t: t.date(),
    "weekly": lambda t: t.date().isocalendar()[:2],
    "monthly": lambda t: (t.year, t.month),
    "yearly": lambda t: t.year,
}


def _parse(snapshot: object) -> datetime:
    if not isinstance(snapshot, str) or not _SHAPE.fullmatch(snapshot):
        raise RetentionError(f"not a snapshot timestamp: {snapshot!r}")
    try:
        return datetime.strptime(snapshot, _FORMAT)
    except ValueError:
        raise RetentionError(f"not a real date and time: {snapshot!r}") from None


def _check_policy(policy: object) -> None:
    if not isinstance(policy, dict):
        raise RetentionError(f"policy must be a dict, not {type(policy).__name__}")
    for rule, n in policy.items():
        if rule not in _RULES:
            raise RetentionError(f"unknown rule: {rule!r}")
        if isinstance(n, bool) or not isinstance(n, int):
            raise RetentionError(f"{rule} must be an int, not {n!r}")
        if n < 0:
            raise RetentionError(f"{rule} must not be negative: {n}")
    if not any(n > 0 for n in policy.values()):
        raise RetentionError("policy keeps nothing")


def retain(snapshots: list[str], policy: dict) -> list[Kept]:
    """Return the snapshots `policy` keeps, newest first, with the rules that keep each."""
    _check_policy(policy)
    parsed = [(s, _parse(s)) for s in snapshots]
    if len({s for s, _ in parsed}) != len(parsed):
        raise RetentionError("the same snapshot appears more than once")
    newest_first = sorted(parsed, key=lambda p: p[1], reverse=True)

    reasons: dict[str, list[str]] = {s: [] for s, _ in newest_first}
    for rule in _RULES:
        n = policy.get(rule, 0)
        if n == 0:
            continue
        bucket_of = _BUCKET[rule]
        seen_buckets: set[object] = set()
        newest_per_bucket: list[str] = []
        for s, t in newest_first:
            key = bucket_of(t)
            if key not in seen_buckets:
                seen_buckets.add(key)
                newest_per_bucket.append(s)
        for s in newest_per_bucket[:n]:
            reasons[s].append(rule)

    return [Kept(s, tuple(reasons[s])) for s, _ in newest_first if reasons[s]]
